class Solution { fun spiralMatrixIII(rows:Int,cols:Int,rStart:Int,cStart:Int):Array<IntArray>{val answer=Array(rows*cols){IntArray(2)};var count=0;answer[count++]=intArrayOf(rStart,cStart);val directions=arrayOf(intArrayOf(0,1),intArrayOf(1,0),intArrayOf(0,-1),intArrayOf(-1,0));var direction=0;var steps=1;var row=rStart;var column=cStart;while(count<answer.size){repeat(2){repeat(steps){row+=directions[direction][0];column+=directions[direction][1];if(row in 0 until rows&&column in 0 until cols)answer[count++]=intArrayOf(row,column)};direction=(direction+1)%4};steps++};return answer} }
